(()=>{"use strict";const $=id=>document.getElementById(id);let watchId=null,lastT=null,lastV=null,speedKmh=0,gFiltered=0;let ctx=null,master=null,engine=null,running=false,profile="cyber",testTimer=null;function initAudio(){if(ctx)return;ctx=new(window.AudioContext||window.webkitAudioContext)({latencyHint:"interactive"});master=ctx.createGain();master.gain.value=Number($("volume").value)/100*.58;const comp=ctx.createDynamicsCompressor();comp.threshold.value=-18;comp.knee.value=16;comp.ratio.value=4;comp.attack.value=.004;comp.release.value=.15;master.connect(comp).connect(ctx.destination);}function osc(type,freq,gain,out){const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.value=freq;g.gain.value=gain;o.connect(g).connect(out);o.start();return{o,g};}function noise(out,gain=.02,freq=1200,type="bandpass"){const b=ctx.createBuffer(1,ctx.sampleRate,ctx.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;const s=ctx.createBufferSource(),f=ctx.createBiquadFilter(),g=ctx.createGain();s.buffer=b;s.loop=true;f.type=type;f.frequency.value=freq;f.Q.value=.7;g.gain.value=gain;s.connect(f).connect(g).connect(out);s.start();return{s,f,g};}function stopEngine(){if(!engine)return;const e=engine;engine=null;try{e.out.gain.setTargetAtTime(.0001,ctx.currentTime,.18)}catch{}setTimeout(()=>{try{e.nodes.forEach(n=>n.stop&&n.stop())}catch{}},180);}function buildEngine(){initAudio();stopEngine();const out=ctx.createGain();out.gain.value=.50;out.connect(master);let e={kind:profile,out,nodes:[]},a,b,c,n;if(profile==="cyber"){a=osc("sine",82,.22,out);b=osc("triangle",164,.09,out);c=osc("sine",650,.014,out)}if(profile==="pod"){a=osc("sawtooth",52,.12,out);b=osc("triangle",104,.11,out);n=noise(out,.018,650)}if(profile==="hyper"){a=osc("sine",46,.24,out);b=osc("triangle",92,.08,out);c=osc("sine",420,.016,out)}if(profile==="turbine"){a=osc("sine",98,.18,out);b=osc("triangle",196,.055,out);n=noise(out,.025,1300)}if(profile==="ion"){a=osc("sine",115,.16,out);b=osc("triangle",345,.045,out);c=osc("sine",1220,.010,out);n=noise(out,.010,1800,"highpass")}if(profile==="phantom"){a=osc("sine",34,.25,out);b=osc("triangle",68,.075,out);c=osc("sine",136,.025,out)}if(profile==="arc"){a=osc("triangle",74,.15,out);b=osc("sine",222,.035,out);c=osc("sine",980,.012,out)}if(profile==="zen"){a=osc("sine",52,.19,out);b=osc("sine",104,.055,out)}[a,b,c].forEach(x=>{if(x)e.nodes.push(x.o)});if(n)e.nodes.push(n.s);e.a=a;e.b=b;e.c=c;e.n=n;engine=e;}function setF(x,val,t,tau=.03){if(x)x.o.frequency.setTargetAtTime(val,t,tau)}function updateEngine(){if(!running||!engine||!ctx)return;const t=ctx.currentTime,sp=Math.min(1.35,Math.max(0,speedKmh/170)),boost=Math.min(1.2,Math.max(0,gFiltered/.42)),decel=Math.min(1,Math.max(0,-gFiltered/.32)),drive=Math.min(1.4,sp*.58+boost*.88),e=engine;if(e.kind==="cyber"){setF(e.a,82+sp*220+boost*115,t,.12);setF(e.b,164+sp*440+boost*220,t,.12);setF(e.c,650+drive*1250,t,.12)}if(e.kind==="pod"){setF(e.a,52+sp*150+boost*95,t,.15);setF(e.b,104+sp*290+boost*175,t,.15);if(e.n)e.n.f.frequency.setTargetAtTime(520+drive*1200,t,.15)}if(e.kind==="hyper"){setF(e.a,46+sp*120+boost*75,t,.18);setF(e.b,92+sp*240+boost*145,t,.18);setF(e.c,420+drive*950,t,.15)}if(e.kind==="turbine"){setF(e.a,98+sp*390+boost*170,t,.18);setF(e.b,196+sp*720+boost*310,t,.15);if(e.n)e.n.f.frequency.setTargetAtTime(950+drive*2200,t,.15)}if(e.kind==="ion"){setF(e.a,115+sp*350+boost*150,t,.13);setF(e.b,345+sp*780+boost*280,t,.12);setF(e.c,1220+drive*1750,t,.10);if(e.n)e.n.f.frequency.setTargetAtTime(1500+drive*2600,t,.12)}if(e.kind==="phantom"){setF(e.a,34+sp*72+boost*52,t,.20);setF(e.b,68+sp*145+boost*100,t,.18);setF(e.c,136+sp*285+boost*190,t,.18)}if(e.kind==="arc"){setF(e.a,74+sp*245+boost*120,t,.12);setF(e.b,222+sp*620+boost*230,t,.12);setF(e.c,980+drive*1550,t,.10)}if(e.kind==="zen"){setF(e.a,52+sp*65,t,.22);setF(e.b,104+sp*130,t,.22)}e.out.gain.setTargetAtTime(Math.max(.24,.43+boost*.22-decel*.09),t,.18);}function onPosition(p){const s=p.coords.speed;if(typeof s!=="number"||!isFinite(s)||s<0){$("gpsText").textContent="GPS CONNECTED · NO SPEED";return}const now=p.timestamp||Date.now();speedKmh=s*3.6;if(lastT!==null&&lastV!==null){const dt=(now-lastT)/1000;if(dt>.08&&dt<5){let raw=(s-lastV)/dt/9.80665;raw=Math.max(-1.1,Math.min(1.1,raw));const alpha=Math.abs(raw)>Math.abs(gFiltered)?.18:.08;gFiltered+=(raw-gFiltered)*alpha;}}lastT=now;lastV=s;$("gpsDot").classList.add("ok");$("gpsText").textContent="GPS CONNECTED";$("gpsFooter").textContent="Active";}function stopGPS(){if(watchId!==null&&navigator.geolocation){navigator.geolocation.clearWatch(watchId);}watchId=null;lastT=null;lastV=null;$("gpsDot").classList.remove("ok");$("gpsText").textContent="GPS NOT CONNECTED";$("gpsFooter").textContent="Inactive";$("gpsToggle").textContent="ENABLE GPS";}function startGPS(){if(!navigator.geolocation){$("gpsText").textContent="GPS NOT AVAILABLE";$("gpsFooter").textContent="Unavailable";return;}if(watchId!==null){stopGPS();return;}$("gpsText").textContent="GPS REQUESTED";$("gpsFooter").textContent="Requesting";watchId=navigator.geolocation.watchPosition(onPosition,()=>{$("gpsDot").classList.remove("ok");$("gpsText").textContent="GPS ERROR";$("gpsFooter").textContent="Error";if(watchId!==null){navigator.geolocation.clearWatch(watchId);watchId=null;}$("gpsToggle").textContent="ENABLE GPS";},{enableHighAccuracy:true,maximumAge:0,timeout:10000});$("gpsToggle").textContent="STOP GPS";}function setProfile(p){profile=p;document.querySelectorAll(".sound-btn").forEach(b=>b.classList.toggle("active",b.dataset.p===p));if(running)buildEngine();}document.querySelectorAll(".sound-btn").forEach(b=>b.onclick=()=>setProfile(b.dataset.p));$("startBtn").onclick=async()=>{initAudio();if(ctx.state==="suspended")await ctx.resume();running=!running;if(running){buildEngine();$("startBtn").textContent="STOP SOUND";$("startBtn").classList.add("running")}else{stopEngine();$("startBtn").textContent="START SOUND";$("startBtn").classList.remove("running")}};$("testBtn").onclick=async()=>{initAudio();if(ctx.state==="suspended")await ctx.resume();if(!running){running=true;buildEngine();$("startBtn").textContent="STOP SOUND";$("startBtn").classList.add("running")}clearInterval(testTimer);let t=0;speedKmh=0;gFiltered=0;testTimer=setInterval(()=>{t+=.05;if(t<1.8){gFiltered=.34;speedKmh+=2.2}else if(t<3.4){gFiltered=.12;speedKmh+=.8}else if(t<4.6){gFiltered=.02;speedKmh+=.12}else if(t<6){gFiltered=-.17;speedKmh=Math.max(0,speedKmh-1.5)}else{clearInterval(testTimer);testTimer=null;speedKmh=0;gFiltered=0}},50);};$("volume").oninput=()=>{const v=Number($("volume").value);$("volPercent").textContent=v+"%";if(ctx&&master)master.gain.setTargetAtTime(v/100*.58,ctx.currentTime,.12);};$("refreshBtn").onclick=()=>window.location.reload();function render(){const boost=Math.round(Math.max(0,Math.min(1,gFiltered/.42))*100),decel=Math.round(Math.max(0,Math.min(1,-gFiltered/.32))*100);let state="CRUISE",sub="Steady speed";if(speedKmh<2&&Math.abs(gFiltered)<.03){state="READY";sub="Waiting for movement"}else if(speedKmh<10&&gFiltered>.14){state="LAUNCH";sub="Strong acceleration"}else if(gFiltered>.07){state="BOOST";sub="Acceleration"}else if(gFiltered<-.06){state="DECEL";sub="Deceleration"}$("speed").textContent=Math.round(speedKmh);$("driveMode").textContent=state;$("driveSub").textContent=sub;$("gValue").textContent=(gFiltered>=0?"+":"")+gFiltered.toFixed(2)+" g";$("boostValue").textContent=boost+" %";$("decelValue").textContent=decel+" %";$("wavePath").setAttribute("transform","translate(0 "+(-Math.max(-8,Math.min(8,gFiltered*20)))+")");updateEngine();requestAnimationFrame(render);}requestAnimationFrame(render);$("gpsToggle").onclick=startGPS;window.addEventListener("pagehide",()=>{try{stopEngine()}catch{}try{stopGPS()}catch{}if(ctx&&ctx.state!=="closed"){try{ctx.close()}catch{}}});document.addEventListener("visibilitychange",()=>{if(document.hidden&&ctx&&ctx.state==="running"){ctx.suspend().catch(()=>{});}else if(!document.hidden&&running&&ctx&&ctx.state==="suspended"){ctx.resume().catch(()=>{});}});if("serviceWorker" in navigator)window.addEventListener("load",()=>navigator.serviceWorker.register("./service-worker.js",{scope:"./"}).catch(()=>{}));})();